class Rules(unittest.TestCase):
    def test_matches_stdlib_isocalendar_for_every_day_1800_2200(self):
        for d in ref_date_range():
            y, w, wd = d.isocalendar()
            self.assertEqual(iso_week(d.year, d.month, d.day), (y, w, wd), d)

    def test_week1_contains_first_thursday(self):
        # 2026-01-01 is a Thursday -> week 1 of 2026
        self.assertEqual(iso_week(2026, 1, 1), (2026, 1, 4))
        self.assertEqual(iso_week(2025, 12, 29), (2026, 1, 1))  # Monday of week 1 of 2026

    def test_dec29_to_31_can_be_week1_of_next_year(self):
        self.assertEqual(iso_week(2024, 12, 30), (2025, 1, 1))
        self.assertEqual(iso_week(2024, 12, 31), (2025, 1, 2))
        self.assertEqual(iso_week(2025, 12, 31), (2026, 1, 3))

    def test_jan1_to_3_can_be_last_week_of_previous_year(self):
        self.assertEqual(iso_week(2021, 1, 1), (2020, 53, 5))
        self.assertEqual(iso_week(2021, 1, 3), (2020, 53, 7))
        self.assertEqual(iso_week(2016, 1, 1), (2015, 53, 5))
        self.assertEqual(iso_week(2010, 1, 1), (2009, 53, 5))

    def test_weekday_monday_is_1_sunday_is_7(self):
        self.assertEqual(iso_week(2026, 10, 12)[2], 1)  # Monday
        self.assertEqual(iso_week(2026, 10, 11)[2], 7)  # Sunday

    def test_week_in_range_1_to_53(self):
        for d in ref_date_range():
            _, w, wd = iso_week(d.year, d.month, d.day)
            self.assertTrue(1 <= w <= 53 and 1 <= wd <= 7)

    def test_nonexistent_dates_raise(self):
        for args in [(2026, 2, 29), (2026, 13, 1), (2026, 0, 1), (2026, 1, 0),
                     (2026, 4, 31), (1900, 2, 29), (2100, 2, 29)]:
            with self.assertRaises(ValueError, msg=str(args)):
                iso_week(*args)

    def test_leap_days_exist_when_leap(self):
        self.assertEqual(iso_week(2000, 2, 29)[0], 2000)
        self.assertEqual(iso_week(2024, 2, 29)[0], 2024)

    def test_stdlib_modules_not_used(self):
        src = open(isoweek.__file__).read()
        for mod in ("datetime", "calendar", "time"):
            self.assertNotIn(f"import {mod}", src)
            self.assertNotIn(f"from {mod}", src)

    def test_from_iso_week53_of_52_week_year_raises(self):
        self.assertEqual(iso_week(2025, 12, 28)[1], 52)  # 2025 has 52 weeks
        with self.assertRaises(ValueError):
            from_iso(2025, 53, 1)

    def test_from_iso_week53_valid_in_53_week_years(self):
        self.assertEqual(from_iso(2026, 53, 4), (2026, 12, 31))
        self.assertEqual(from_iso(2020, 53, 5), (2021, 1, 1))

    def test_from_iso_week0_raises(self):
        with self.assertRaises(ValueError):
            from_iso(2026, 0, 1)

    def test_from_iso_week54_raises(self):
        with self.assertRaises(ValueError):
            from_iso(2026, 54, 1)

    def test_from_iso_weekday_out_of_range_raises(self):
        for wd in (0, 8, -1):
            with self.assertRaises(ValueError, msg=str(wd)):
                from_iso(2026, 1, wd)

    def test_from_iso_round_trip_every_day(self):
        for d in ref_date_range():
            y, w, wd = d.isocalendar()
            self.assertEqual(from_iso(y, w, wd), (d.year, d.month, d.day), d)

    def test_from_iso_every_valid_week_matches_stdlib(self):
        # Every (year, week, weekday) that the stdlib accepts must map back to the same date;
        # every one it rejects must raise here.
        for y in range(1800, 2201):
            for w in range(1, 55):
                for wd in range(1, 8):
                    try:
                        ref = datetime.date.fromisocalendar(y, w, wd)
                    except ValueError:
                        ref = None
                    if ref is None:
                        with self.assertRaises(ValueError, msg=(y, w, wd)):
                            from_iso(y, w, wd)
                    else:
                        self.assertEqual(from_iso(y, w, wd), (ref.year, ref.month, ref.day))


if __name__ == "__main__":
    unittest.main(verbosity=1)
